SELECT CONCAT(first_name, last_name) AS a, SUBSTR(first_name, 1, 3) AS b, REGEXP_EXTRACT(first_name, r'^(\w)') AS c, REGEXP_REPLACE(first_name, r'a', 'b') AS d, SPLIT(first_name, 'a') AS e, FORMAT('%s-%d', state, age) AS f, LPAD(state, 5, '*') AS g, TRIM(first_name) AS h, STARTS_WITH(first_name, 'A') AS i, REGEXP_CONTAINS(first_name, r'x') AS j, TO_BASE64(MD5(first_name)) AS k, SHA256(first_name) AS l, GENERATE_UUID() AS m, FARM_FINGERPRINT(first_name) AS n FROM `kumosql.kumosql_messy.raw_users`
